// wantGatewayError checks a response generated by the gateway itself.
// retryAfter < 0 means no Retry-After header; 0 means any value >= 1.
func wantGatewayError(t *testing.T, resp *http.Response, status int, code string, retryAfter int) {
	t.Helper()
	defer func() { _ = resp.Body.Close() }()
	body := readBody(t, resp)
	if resp.StatusCode != status || resp.Header.Get("Sbx-Error") != code {
		t.Fatalf("got %d %q, want %d %q (body %s)", resp.StatusCode, resp.Header.Get("Sbx-Error"), status, code, body)
	}
	if got := resp.Header.Get("Cache-Control"); got != "no-store" {
		t.Errorf("Cache-Control = %q", got)
	}
	if got := resp.Header.Values("X-Robots-Tag"); len(got) != 1 || got[0] != "noindex, nofollow" {
		t.Errorf("X-Robots-Tag = %q", got)
	}
	if resp.Header.Get("X-Request-Id") == "" {
		t.Error("no X-Request-Id")
	}
	ra := resp.Header.Get("Retry-After")
	switch {
	case retryAfter < 0 && ra != "":
		t.Errorf("Retry-After = %q, want none", ra)
	case retryAfter == 0:
		if n, err := strconv.Atoi(ra); err != nil || n < 1 {
			t.Errorf("Retry-After = %q, want >= 1", ra)
		}
	case retryAfter > 0 && ra != strconv.Itoa(retryAfter):
		t.Errorf("Retry-After = %q, want %d", ra, retryAfter)
	}
	for _, leak := range []string{"sbx.internal", "machine", "gw-", "127.0.0.1"} {
		if strings.Contains(body, leak) {
			t.Errorf("body leaks %q: %s", leak, body)
		}
	}
}

// expectError sends req and checks the gateway's answer.
func expectError(t *testing.T, c *http.Client, req *http.Request, status int, code string, retryAfter int) {
	t.Helper()
	resp := do(t, c, req)
	defer func() { _ = resp.Body.Close() }()
	defer func() { _ = resp.Body.Close() }()
	wantGatewayError(t, resp, status, code, retryAfter)
}

func TestErrorTable(t *testing.T) {
	env := testenv.New(t, testenv.Options{})
	inst := env.StartInstance(func(c *config.Config) {
		c.Timeouts.AgentWait = 300 * time.Millisecond
		c.Timeouts.Dial = time.Second
		c.Timeouts.ResponseHeader = time.Second
	})
	m := env.NewMachine()
	c := env.PlainClient(inst)

	m.ServeHTTP(3000, echoApp())
	m.ServeHTTP(3002, http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		select {
		case <-time.After(5 * time.Second):
		case <-r.Context().Done():
		}
	}))
	m.ServeTCP(3003, func(c net.Conn) {
		_, _ = bufio.NewReader(c).ReadString('\n')
		_, _ = io.WriteString(c, "NOT HTTP AT ALL\r\n\r\n")
	})
	m.Blackhole(3004)
	m.ServeHTTP(3005, http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("X-Big", strings.Repeat("a", 70<<10))
	}))

	route := func(port uint16, mod func(*cpapi.Route)) string {
		return testenv.Host(env.Route(m, port, mod).Label)
	}
	get := func(t *testing.T, host string, hdr ...string) *http.Response {
		t.Helper()
		req := newReq(t, http.MethodGet, host, "/", nil)
		for i := 0; i+1 < len(hdr); i += 2 {
			req.Header.Set(hdr[i], hdr[i+1])
		}
		return do(t, c, req)
	}

	rows := []struct {
		name       string
		host       func() string
		hdr        []string
		status     int
		code       string
		retryAfter int
	}{
		{"bad host", func() string { return "example.com" }, nil, 404, "route_not_found", -1},
		{"apex", func() string { return testenv.SbxDomain }, nil, 404, "route_not_found", -1},
		{"unknown label", func() string { return testenv.Host("nosuch-3000") }, nil, 404, "route_not_found", -1},
		{"reserved port", func() string { return testenv.Host("abc-22") }, nil, 404, "route_not_found", -1},
		{"desktop without handler", func() string { return testenv.Host("myapp-desktop") }, nil, 404, "route_not_found", -1},
		{"deleted", func() string { return route(3000, func(r *cpapi.Route) { r.SandboxState = "deleted" }) }, nil, 404, "route_not_found", -1},
		{"blocked operator", func() string {
			return route(3000, func(r *cpapi.Route) { r.Blocked = true; r.BlockReason = "operator" })
		}, nil, 403, "route_blocked", -1},
		{"public disabled", func() string {
			return route(3000, func(r *cpapi.Route) { r.Blocked = true; r.BlockReason = "public_disabled" })
		}, nil, 403, "route_blocked", -1},
		{"auth required", func() string {
			return route(3000, func(r *cpapi.Route) { r.Access = "token"; r.TokenHash = tokenHash("t") })
		}, []string{"Accept", "application/json"}, 401, "auth_required", -1},
		{"token invalid", func() string {
			return route(3000, func(r *cpapi.Route) { r.Access = "token"; r.TokenHash = tokenHash("t") })
		}, []string{"Sbx-Port-Token", "wrong"}, 401, "token_invalid", -1},
		{"app not listening", func() string { return route(3001, nil) }, nil, 502, "app_not_listening", -1},
		{"upstream error", func() string { return route(3003, nil) }, nil, 502, "upstream_error", -1},
		{"response header too large", func() string { return route(3005, nil) }, nil, 502, "upstream_error", -1},
		{"response header timeout", func() string { return route(3002, nil) }, nil, 504, "app_timeout", -1},
		{"dial timeout", func() string { return route(3004, nil) }, nil, 504, "app_timeout", -1},
		{"sandbox starting", func() string { return route(3000, func(r *cpapi.Route) { r.SandboxState = "starting" }) }, nil, 503, "sandbox_starting", 5},
		{"sandbox stopped", func() string { return route(3000, func(r *cpapi.Route) { r.SandboxState = "stopped" }) }, nil, 503, "sandbox_stopped", -1},
		{"sandbox unavailable", func() string { return route(3000, func(r *cpapi.Route) { r.SandboxState = "error" }) }, nil, 503, "sandbox_unavailable", -1},
		{"ready without machine", func() string { return route(3000, func(r *cpapi.Route) { r.MachineID = "" }) }, nil, 503, "sandbox_unavailable", -1},
		{"agent unavailable", func() string {
			return route(3000, func(r *cpapi.Route) { r.MachineID = uuid.NewString() })
		}, []string{"Accept", "text/html"}, 503, "agent_unavailable", 5},
	}
	for _, row := range rows {
		t.Run(row.name, func(t *testing.T) {
			resp := get(t, row.host(), row.hdr...)
			defer func() { _ = resp.Body.Close() }()
			wantGatewayError(t, resp, row.status, row.code, row.retryAfter)
		})
	}

	t.Run("agent unavailable page refreshes", func(t *testing.T) {
		host := route(3000, func(r *cpapi.Route) { r.MachineID = uuid.NewString() })
		resp := get(t, host, "Accept", "text/html")
		defer func() { _ = resp.Body.Close() }()
		if body := readBody(t, resp); !strings.Contains(body, `http-equiv="refresh"`) {
			t.Errorf("no refresh in %s", body)
		}
	})

	t.Run("route lookup unavailable", func(t *testing.T) {
		host := route(3000, nil)
		env.API.SetDown(true)
		defer env.API.SetDown(false)
		resp := get(t, host)
		defer func() { _ = resp.Body.Close() }()
		wantGatewayError(t, resp, 503, "route_lookup_unavailable", -1)
		// The reserved endpoints refuse too instead of acting without a route.
		resp = do(t, c, newReq(t, http.MethodGet, host, "/__sbx/auth/callback?code=x&state=y", nil))
		defer func() { _ = resp.Body.Close() }()
		wantGatewayError(t, resp, 503, "route_lookup_unavailable", -1)
	})

	t.Run("reserved path is never proxied", func(t *testing.T) {
		expectError(t, c, newReq(t, http.MethodGet, route(3000, nil), "/__sbx/other", nil), 404, "route_not_found", -1)
	})

	t.Run("ip rate limit", func(t *testing.T) {
		limited := env.StartInstance(func(c *config.Config) {
			c.RateLimit.IPRate = 0.001
			c.RateLimit.IPBurst = 2
		})
		lc := env.PlainClient(limited)
		host := testenv.Host("nosuch-3000")
		for range 2 {
			expectError(t, lc, newReq(t, http.MethodGet, host, "/", nil), 404, "route_not_found", -1)
		}
		expectError(t, lc, newReq(t, http.MethodGet, host, "/", nil), 429, "rate_limited", 0)
	})

	t.Run("label rate limit", func(t *testing.T) {
		limited := env.StartInstance(func(c *config.Config) {
			c.RateLimit.LabelRate = 0.001
			c.RateLimit.LabelBurst = 1
		})
		lc := env.PlainClient(limited)
		// Unknown labels never reach the label limit.
		for range 3 {
			expectError(t, lc, newReq(t, http.MethodGet, testenv.Host("nosuch-3000"), "/", nil), 404, "route_not_found", -1)
		}
		host := route(3000, nil)
		resp := do(t, lc, newReq(t, http.MethodGet, host, "/", nil))
		defer func() { _ = resp.Body.Close() }()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("first request = %d %s", resp.StatusCode, resp.Header.Get("Sbx-Error"))
		}
		expectError(t, lc, newReq(t, http.MethodGet, host, "/", nil), 429, "rate_limited", 0)
	})
}

func TestErrorOverloaded(t *testing.T) {
	env := testenv.New(t, testenv.Options{Deps: func(d *server.Deps) { d.MaxTCPStreamsPerMachine = 1 }})
	inst := env.StartInstance(nil)
	m := env.NewMachine()
	m.ServeTCP(4000, testenv.Echo)
	m.ServeHTTP(3000, echoApp())

	ctx, cancel := context.WithTimeout(context.Background(), reqTimeout)
	defer cancel()
	held, err := inst.Upstream().Dial(ctx, m.ID, 4000, time.Second)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = held.Close() }()

	host := testenv.Host(env.Route(m, 3000, nil).Label)
	resp := do(t, env.PlainClient(inst), newReq(t, http.MethodGet, host, "/", nil))
	defer func() { _ = resp.Body.Close() }()
	wantGatewayError(t, resp, 503, "overloaded", -1)
}

func TestClientGoneIsLogged(t *testing.T) {
	f := newFixture(t, nil)
	f.m.ServeHTTP(3000, http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		<-r.Context().Done()
	}))
	rt := f.env.Route(f.m, 3000, nil)
	ctx, cancel := context.WithCancel(context.Background())
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://"+testenv.Host(rt.Label)+"/", nil)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("X-Request-Id", "gone-1")
	go func() {
		time.Sleep(200 * time.Millisecond)
		cancel()
	}()
	if resp, err := f.c.Do(req); err == nil {
		_ = resp.Body.Close()
		t.Fatal("request finished")
	}
	if l := logLine(t, f.inst, "gone-1"); l["status"] != 499.0 {
		t.Errorf("access log status = %v, want 499", l["status"])
	}
}

func h2cTransport(inst *testenv.Inst) *http.Transport {
	var p http.Protocols
	p.SetUnencryptedHTTP2(true)
	return &http.Transport{
		Protocols: &p,
		DialContext: func(ctx context.Context, network, _ string) (net.Conn, error) {
			return (&net.Dialer{}).DialContext(ctx, network, inst.PlainAddr)
		},
	}
}

func TestH2CApp(t *testing.T) {
	f := newFixture(t, nil)
	f.m.ServeH2C(5000, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Trailer", "Grpc-Status, Sbx-Bad")
		w.Header().Set("Content-Type", "application/grpc")
		w.WriteHeader(http.StatusOK)
		rc := http.NewResponseController(w)
		_ = rc.Flush()
		sc := bufio.NewScanner(r.Body)
		for sc.Scan() {
			_, _ = io.WriteString(w, "echo:"+sc.Text()+"\n")
			_ = rc.Flush()
		}
		w.Header().Set("Grpc-Status", "0")
		w.Header().Set("Sbx-Bad", "x")
	}))
	rt := f.env.Route(f.m, 5000, func(r *cpapi.Route) { r.AppProtocol = "h2c" })
	host := testenv.Host(rt.Label)

	t.Run("bidi with trailers over HTTP/2", func(t *testing.T) {
		tr := h2cTransport(f.inst)
		defer tr.CloseIdleConnections()
		pr, pw := io.Pipe()
		defer func() { _ = pw.Close() }()
		req := newReq(t, http.MethodPost, host, "/svc.Echo/Bidi", pr)
		req.Header.Set("X-Request-Id", "h2c-bidi")
		resp, err := tr.RoundTrip(req)
		if err != nil {
			t.Fatal(err)
		}
		defer func() { _ = resp.Body.Close() }()
		if resp.StatusCode != http.StatusOK || resp.ProtoMajor != 2 {
			t.Fatalf("status %d proto %s", resp.StatusCode, resp.Proto)
		}
		br := bufio.NewReader(resp.Body)
		for _, msg := range []string{"ping1", "ping2", "ping3"} {
			if _, err := io.WriteString(pw, msg+"\n"); err != nil {
				t.Fatal(err)
			}
			line, err := br.ReadString('\n')
			if err != nil || line != "echo:"+msg+"\n" {
				t.Fatalf("line = %q, %v", line, err)
			}
		}
		_ = pw.Close()
		if rest, err := io.ReadAll(br); err != nil || len(rest) != 0 {
			t.Fatalf("rest = %q, %v", rest, err)
		}
		if resp.Trailer.Get("Grpc-Status") != "0" {
			t.Errorf("Grpc-Status trailer = %q (trailers %v)", resp.Trailer.Get("Grpc-Status"), resp.Trailer)
		}
		if _, ok := resp.Trailer["Sbx-Bad"]; ok {
			t.Errorf("Sbx-Bad reached the client: %v", resp.Trailer)
		}
		if l := logLine(t, f.inst, "h2c-bidi"); l["via"] != "local" || l["status"] != 200.0 {
			t.Errorf("access log via=%v status=%v", l["via"], l["status"])
		}
	})

	t.Run("HTTP/1 client", func(t *testing.T) {
		resp := do(t, f.c, newReq(t, http.MethodGet, host, "/", nil))
		defer func() { _ = resp.Body.Close() }()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d %s", resp.StatusCode, resp.Header.Get("Sbx-Error"))
		}
		_ = readBody(t, resp)
	})

	t.Run("upgrade refused", func(t *testing.T) {
		resp, _ := upgradeRequest(t, rawConn(t, f.inst), host, "/h2cup")
		defer func() { _ = resp.Body.Close() }()
		wantGatewayError(t, resp, 502, "upstream_error", -1)
	})
}

func TestNoEnableConnectProtocol(t *testing.T) {
	f := newFixture(t, nil)
	c := rawConn(t, f.inst)
	_ = c.SetDeadline(time.Now().Add(reqTimeout))
	if _, err := io.WriteString(c, http2.ClientPreface); err != nil {
		t.Fatal(err)
	}
	fr := http2.NewFramer(c, c)
	if err := fr.WriteSettings(); err != nil {
		t.Fatal(err)
	}
	for {
		frame, err := fr.ReadFrame()
		if err != nil {
			t.Fatalf("read frame: %v", err)
		}
		sf, ok := frame.(*http2.SettingsFrame)
		if !ok || sf.IsAck() {
			continue
		}
		n := 0
		_ = sf.ForeachSetting(func(s http2.Setting) error {
			n++
			if s.ID == http2.SettingEnableConnectProtocol {
				t.Errorf("server SETTINGS has ENABLE_CONNECT_PROTOCOL=%d", s.Val)
			}
			return nil
		})
		if n == 0 {
			t.Fatal("empty server SETTINGS")
		}
		return
	}
}

// rawApp answers every HTTP/1.1 request on port with raw and closes the
// conn.
func rawApp(m *testenv.Machine, port uint16, raw string) {
	m.ServeTCP(port, func(c net.Conn) {
		if _, err := http.ReadRequest(bufio.NewReader(c)); err != nil {
			return
		}
		_, _ = io.WriteString(c, raw)
	})
}

// The response header cap counts the HTTP/2 size of the block (name, value
// and 32 per field), what a coalesced browser conn receives: 10,000 tiny
// fields fit the transport's 64 KiB byte limit on the wire but are 340 KB
// as an HTTP/2 header list.
func TestResponseHeaderCap(t *testing.T) {
	f := newFixture(t, nil)
	rawApp(f.m, 3000, "HTTP/1.1 200 OK\r\n"+strings.Repeat("X: v\r\n", 10000)+"Content-Length: 2\r\n\r\nok")
	// 1,500 fields: 51,000 bytes as HTTP/2, under the cap.
	rawApp(f.m, 3001, "HTTP/1.1 200 OK\r\n"+strings.Repeat("X: v\r\n", 1500)+"Content-Length: 2\r\n\r\nok")
	// Few fields, 63 KiB as HTTP/2 with the gateway's own headers: under.
	rawApp(f.m, 3002, "HTTP/1.1 200 OK\r\nX-Big: "+strings.Repeat("b", 62<<10)+"\r\nContent-Length: 2\r\n\r\nok")

	expectError(t, f.c, newReq(t, http.MethodGet, testenv.Host(f.env.Route(f.m, 3000, nil).Label), "/", nil), 502, "upstream_error", -1)
	for _, port := range []uint16{3001, 3002} {
		resp := do(t, f.c, newReq(t, http.MethodGet, testenv.Host(f.env.Route(f.m, port, nil).Label), "/", nil))
		defer func() { _ = resp.Body.Close() }()
		if b := readBody(t, resp); resp.StatusCode != http.StatusOK || b != "ok" {
			t.Fatalf("port %d: %d %q", port, resp.StatusCode, b)
		}
	}
}
